name: AI Moderator

on:
  issue_comment:
    types: [created]
  issues:
    types: [opened, edited]
  pull_request:
    types: [opened, edited]
  pull_request_review_comment:
    types: [created]

permissions:
  issues: write
  pull-requests: write
  contents: read

jobs:
  moderate:
    runs-on: ubuntu-latest
    if: ${{ github.event.sender.type != 'Bot' }}
    steps:
      - name: Run AI Moderator
        uses: actions/ai-inference@v1
        with:
          model: gpt-4o-mini
          prompt: |
            You are an AI moderator for a GitHub repository. Analyze the following content for spam, malicious links, or low-quality AI-generated text.

            Content Type: ${{ github.event_name }}
            Title: ${{ github.event.issue.title || github.event.pull_request.title || '' }}
            Body: ${{ github.event.issue.body || github.event.pull_request.body || github.event.comment.body || '' }}

            If the content appears to be spam, contains suspicious links, or is low-quality AI-generated filler, respond with "SPAM".
            Otherwise, respond with "CLEAN".
          token: ${{ secrets.GITHUB_TOKEN }}
        id: moderation

      - name: Label and Minimize if Spam
        if: ${{ steps.moderation.outputs.response == 'SPAM' }}
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const isIssue = context.payload.issue;
            const isPR = context.payload.pull_request;
            const isComment = context.payload.comment;

            let resourceId;
            let resourceType;

            if (isIssue) {
              resourceId = isIssue.number;
              resourceType = 'issue';
            } else if (isPR) {
              resourceId = isPR.number;
              resourceType = 'pull_request';
            } else if (isComment) {
              resourceId = isComment.id;
              resourceType = 'comment';
            } else {
              return;
            }

            // Add spam label to issue/PR if applicable
            if (resourceType === 'issue' || resourceType === 'pull_request') {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: resourceId,
                labels: ['spam']
              });
            }

            // Minimize the comment/issue/PR as spam
            // Note: GitHub API for minimizing comments is not directly exposed in the standard rest client in a simple way
            // We can add a comment indicating it was flagged, or rely on labels.
            // For true minimization, one might need to use the GraphQL API or specific REST endpoints if available.
            // Here we just add a label and a comment.

            if (isComment) {
               await github.rest.issues.createComment({
                 owner: context.repo.owner,
                 repo: context.repo.repo,
                 issue_number: isComment.issue_url.split('/').pop(),
                 body: 'This comment has been flagged as spam by the AI Moderator.'
               });
            }
